module parallel2serial(
    input clk, 
    input rst_n, 
    input [3:0] d,
    output valid_out, 
    output dout
);
// Sequential logic for counter
reg [1:0] cnt;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        cnt <= 2'd0;
    else if(cnt == 2'd3)
        cnt <= 2'd0;
    else
        cnt <= cnt + 1;
end
// Sequential logic for data register
reg [3:0] data;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        data <= 4'd0;
    else if(cnt == 2'd3)
        data <= d;
    else
        data <= {data[2:0], data[3]};
end
// Sequential logic for valid signal
reg valid;
always @(posedge clk or negedge rst_n) begin
    if(!rst_n)
        valid <= 1'b0;
    else if(cnt == 2'd3)
        valid <= 1'b1;
    else
        valid <= 1'b0;
end
// Assign dout to the MSB of data register
assign dout = data[3];
// Assign valid_out to the valid signal
assign valid_out = valid;
endmodule
